 # ---------------- V. THE CIVILIAN ARMY ----------------
 ("It started with people who were not soldiers.",
  [G("chapter", case="1861 – 1865", n="V", t="THE CIVILIAN ARMY")], dict(gap=1.6, kind="calm")),
